// Each family preserves the narrative order through adjacent rooms. Variation
// belongs to the saved View, so reopening it never rearranges a familiar visit.
export function exhibitionLayoutSeed(identity) {
  let hash = 2166136261;
  for (const character of String(identity)) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0;
  return (hash ^ (hash >>> 16)) >>> 0;
}

export function createExhibitionFloorplan(sections, seed = 0, family = 'courtyard') {
  const inputs = Array.isArray(sections) ? sections : [];
  const sizes = inputs.map(section => {
    const works = Number.isFinite(section.works) ? Math.max(0, section.works) : (section.blocks || []).filter(block => block.kind === 'source').length;
    return { width: section.width || Math.max(16, Math.min(24, 16 + works)), depth: section.depth || Math.max(20, 10 + works * 4.2) };
  });
  const pitch = Math.max(20, ...sizes.flatMap(size => [size.width, size.depth])) + 4;
  const cells = [];
  let x = 0, z = 0, run = 1, direction = 0;
  const directions = [[1,0],[0,-1],[-1,0],[0,1]];
  const transform = (x,z) => {
    let a = seed & 4 ? -x : x, b = z;
    for (let turn = 0; turn < (seed & 3); turn++) [a,b] = [-b,a];
    return [a,b];
  };
  if (family === 'linear' || family === 'corner') {
    const bend = Math.max(2, Math.min(inputs.length - 1, Math.ceil(inputs.length * (.45 + (seed % 3) * .05))));
    for (let i=0;i<inputs.length;i++) {
      cells.push(transform(family === 'corner' && i >= bend ? i-bend+2 : 1, family === 'corner' && i >= bend ? -(bend-1) : -i));
    }
  }
  while (cells.length < inputs.length) {
    for (let twice = 0; twice < 2 && cells.length < inputs.length; twice++) {
      const [dx,dz] = directions[direction % 4];
      for (let step = 0; step < run && cells.length < inputs.length; step++) {
        x += dx; z += dz;
        cells.push(transform(x,z));
      }
      direction++;
    }
    run++;
  }
  const rooms = inputs.map((section,index) => ({ index, id: section.id ?? String(index), title: section.heading || section.title || String(index + 1), cell: cells[index], x: cells[index][0] * pitch, z: cells[index][1] * pitch, ...sizes[index] }));
  const doors = [], degrees = new Array(rooms.length).fill(0);
  function connect(a,b,primary) {
    const first=rooms[a], second=rooms[b], dx=Math.sign(second.x-first.x), dz=Math.sign(second.z-first.z);
    doors.push({ a,b,primary,width:3.7,points:[[first.x+dx*first.width/2,first.z+dz*first.depth/2],[second.x-dx*second.width/2,second.z-dz*second.depth/2]] });
    degrees[a]++; degrees[b]++;
  }
  for (let index=1;index<rooms.length;index++) connect(index-1,index,true);
  const occupied = new Map(rooms.map(room=>[room.cell.join(','),room.index]));
  for (const room of rooms) for (const [dx,dz] of [[1,0],[0,1]]) {
    const neighbour=occupied.get([room.cell[0]+dx,room.cell[1]+dz].join(','));
    if (neighbour !== undefined && Math.abs(neighbour-room.index)>1 && degrees[room.index]<3 && degrees[neighbour]<3) connect(room.index,neighbour,false);
  }
  return { rooms, doors, family, seed, courtyard: { x:0,z:0,width:pitch-4,depth:pitch-4 }, pitch };
}

export function exhibitionRoomRoute(plan, start, target) {
  if (!plan.rooms[start] || !plan.rooms[target]) return [];
  const distances = new Map([[start,0]]), previous = new Map(), pending = new Set(plan.rooms.map(room=>room.index));
  while (pending.size) {
    let current=null, minimum=Infinity;
    for (const index of pending) if ((distances.get(index) ?? Infinity)<minimum) { current=index; minimum=distances.get(index); }
    if (current===null) return [];
    pending.delete(current);
    if (current===target) {
      const path=[target];
      while(path[0]!==start) path.unshift(previous.get(path[0]));
      return path;
    }
    for (const door of plan.doors) {
      const next=door.a===current?door.b:door.b===current?door.a:null;
      if (next===null || !pending.has(next)) continue;
      const a=plan.rooms[current],b=plan.rooms[next],distance=minimum+Math.hypot(a.x-b.x,a.z-b.z);
      if (distance<(distances.get(next)??Infinity)) { distances.set(next,distance); previous.set(next,current); }
    }
  }
  return [];
}
