// Optional presentation metadata. Invalid cues never invalidate the article.
export function exhibitionParagraphs(text) {
  return typeof text === 'string' ? text.split(/\n\s*\n/).map(value => value.trim()).filter(Boolean) : [];
}

export function cleanExhibitionIntro(value) {
  return typeof value === 'string' ? value.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().slice(0, 500) : '';
}

export function cleanExhibitionCues(value, text, availableSources) {
  const count = exhibitionParagraphs(text).length;
  const cues = new Map();
  for (const item of (Array.isArray(value) ? value : value && typeof value === 'object' ? [value] : []).slice(0, 20)) {
    if (!item || typeof item !== 'object') continue;
    const paragraph = item.paragraph == null ? 0 : Number(item.paragraph);
    if (!Number.isInteger(paragraph) || paragraph < 0 || paragraph >= count) continue;
    // An empty focus deliberately keeps the current viewing position.
    const focus = typeof item.focus_source_id === 'string' ? item.focus_source_id.trim() : null;
    if (focus === null || (focus && (focus.length > 180 || availableSources && !availableSources.has(focus)))) continue;
    const highlight = item.highlight === true || item.highlight === 'true';
    cues.set(paragraph, { paragraph, focus_source_id: focus, highlight });
  }
  return [...cues.values()].sort((a, b) => a.paragraph - b.paragraph);
}
